"use strict";
const test=require("node:test"),assert=require("node:assert/strict"),fs=require("node:fs"),path=require("node:path");const {fixture}=require("./helper"),{create}=require("../plugin/service"),Model=require("../plugin/workflow-model");
async function finished(app,id){for(let i=0;i<100;i++){const r=await app.call("workflows.runGet",{id});if(["completed","failed","waiting","cancelled"].includes(r.status))return r;await new Promise(r=>setTimeout(r,10));}throw Error("Workflow did not finish");}
test("real graph executes plugin-owned code and stores only workflow records",async t=>{const f=fixture(t,"kai.workflows"),app=create(f.api);t.after(()=>app.dispose());const graph={version:2,nodes:[Model.node("trigger","start"),Model.node("code","code",undefined,{source:'return [{text:"plugin-owned",value:21*2}];'}),Model.node("output","out")],edges:[Model.edge("start","code"),Model.edge("code","out")]};const w=await app.call("workflows.workflow",{name:"Code graph",graph});const run=await app.call("workflows.run",{id:w.id,input:"hello"});const result=await finished(app,run.id);assert.equal(result.status,"completed",result.error);assert.match(JSON.stringify(result),/plugin-owned/);assert.match(JSON.stringify(result),/42/);const raw=JSON.parse(f.api.secrets.decryptString(Buffer.from(JSON.parse(fs.readFileSync(path.join(f.root,"state.json"))).encrypted,"base64")));for(const key of ["notes","connections","sources","goals","composio"])assert.equal(Object.hasOwn(raw,key),false,key);assert.equal(raw.workflows.length,1);assert.equal(raw.runs.length,1);});
test("workflow expressions have no Node access and infinite loops are bounded",async()=>{const V=require("../plugin/service/workflow-values");assert.equal(await V.evaluate('typeof process',{items:[],item:{},input:"",nodes:{},iteration:0}),"undefined");await assert.rejects(V.evaluate("while(true){}",{items:[],item:{},input:"",nodes:{},iteration:0},undefined,false),/failed/);});
test("exported workflow run requires provider-owned review and preserves saved graph",async t=>{const f=fixture(t,"kai.workflows"),app=create(f.api);t.after(()=>app.dispose());const w=await app.call("workflows.workflow",{name:"Shared",graph:{version:2,nodes:[Model.node("trigger","start"),Model.node("output","out")],edges:[Model.edge("start","out")]}});const service=f.provided.get("kai.workflows"),copy=await service.call("exportService",{id:w.id});copy.graph.nodes[0].label="tampered";assert.notEqual((await service.call("get",{id:w.id})).graph.nodes[0].label,"tampered");f.api.desktop.confirm=async()=>false;await assert.rejects(service.call("run",{id:w.id,input:"anything"}),/not started/);assert.equal((await app.call("workflows.runs")).length,0);});
test("background chat output is granted for an exact workflow revision before scheduling",async t=>{const f=fixture(t,"kai.workflows"),grants=[],saves=[];f.provided.set("kai.assistant",{methods:["chats.grantWrite","chats.save"],call:async(method,input)=>{if(method==="chats.grantWrite"){grants.push(input);return{scope:input.scope};}saves.push(input);return{id:"saved-chat"};}});const app=create(f.api);t.after(()=>app.dispose());const w=await app.call("workflows.workflow",{name:"Save result",enabled:true,graph:{version:2,nodes:[Model.node("trigger","start"),Model.node("output","out",undefined,{text:"Result",saveChat:true})],edges:[Model.edge("start","out")]}});assert.equal(w.enabled,true);assert.equal(grants[0].scope,"workflow:"+w.id+":"+w.revision);const run=await app.call("workflows.run",{id:w.id});assert.equal((await finished(app,run.id)).status,"completed");assert.equal(saves[0].grantScope,grants[0].scope);assert.equal(saves[0].messages[0].content,"Workflow run");});
